package dev.eugheist.ttmodern;
final class AwakenedSwordAudit {
 static void check(boolean ok,String label){if(!ok)throw new IllegalStateException("TT awakened sword: "+label);}
 static void run(net.minecraft.server.MinecraftServer server){var level=server.overworld();var player=new net.neoforged.neoforge.common.util.FakePlayer(level,new com.mojang.authlib.GameProfile(java.util.UUID.randomUUID(),"SwordAudit")){@Override public boolean isInvulnerableTo(net.minecraft.world.damagesource.DamageSource source){return false;}};try{var f=net.minecraft.server.level.ServerPlayer.class.getDeclaredField("spawnInvulnerableTime");f.setAccessible(true);f.setInt(player,0);}catch(ReflectiveOperationException e){throw new IllegalStateException(e);}player.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);player.setPos(5,290,5);var stack=new net.minecraft.world.item.ItemStack(AwakenedSword.ITEM.get());player.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,stack);var center=new net.minecraft.world.entity.animal.Cow(net.minecraft.world.entity.EntityType.COW,level);var near=new net.minecraft.world.entity.animal.Cow(net.minecraft.world.entity.EntityType.COW,level);var far=new net.minecraft.world.entity.animal.Cow(net.minecraft.world.entity.EntityType.COW,level);var pig=new net.minecraft.world.entity.animal.Pig(net.minecraft.world.entity.EntityType.PIG,level);var entities=java.util.List.of(center,near,far,pig);center.setPos(6,290,5);near.setPos(7,290,5);far.setPos(10,290,5);pig.setPos(7,290,6);for(var entity:entities){entity.getAttribute(net.minecraft.world.entity.ai.attributes.Attributes.MAX_HEALTH).setBaseValue(100);entity.setHealth(100);level.addFreshEntity(entity);}
 try{
  player.attack(center);check(center.getHealth()<100&&near.getHealth()==100&&pig.getHealth()==100,"single native Player.attack only selected target");
  for(var entity:entities){entity.setHealth(100);entity.hurtTime=0;entity.invulnerableTime=0;}AdvancedToolModes.change(stack);player.attack(center);check(center.getHealth()<100&&near.getHealth()<100&&far.getHealth()==100&&pig.getHealth()==100,"native area attack same class/range and finite recursion");
  AdvancedToolModes.change(stack);center.hurtTime=0;center.invulnerableTime=0;player.attack(center);check(SoulHearts.get(player)==1,"native soul mode gains exactly one point");var effect=center.getEffect(net.minecraft.world.effect.MobEffects.DAMAGE_RESISTANCE);check(effect!=null&&effect.getDuration()==1&&effect.getAmplifier()==1,"original target resistance II one tick");
  player.attack(center);check(SoulHearts.get(player)==1,"hurtTime blocks repeated soul harvest");
  for(int i=0;i<30;i++)SoulHearts.add(player);check(SoulHearts.get(player)==20,"twenty point cap");
  player.setHealth(20);player.invulnerableTime=0;player.hurt(level.damageSources().generic(),4);check(player.getHealth()==20&&SoulHearts.get(player)==16,"actual damage uses separate soul reserve before health (health="+player.getHealth()+",soul="+SoulHearts.get(player)+")");
  player.hurt(level.damageSources().generic(),4);check(SoulHearts.get(player)==16,"cooldown rejected hit consumes no soul points");SoulHearts.set(player,2);player.invulnerableTime=0;player.hurt(level.damageSources().generic(),5);check(SoulHearts.get(player)==0&&player.getHealth()==17,"overflow reaches ordinary health");
  SoulHearts.set(player,3);var saved=player.getPersistentData().copy();var restored=new net.neoforged.neoforge.common.util.FakePlayer(level,new com.mojang.authlib.GameProfile(java.util.UUID.randomUUID(),"SoulSavedAudit"));restored.getPersistentData().merge(saved);check(SoulHearts.get(restored)==3,"persistent original compound/key");
  var recipe=dev.eugheist.tc4modern.InfusionItemRecipes.all().stream().filter(r->r.key().equals("ICHOR_SWORD_GEM")).findFirst().orElseThrow();check(recipe.componentStacks().size()==12&&recipe.componentStacks().get(2).is(FocusResearch.item("elemental_sword"))&&recipe.componentStacks().get(3).is(FocusResearch.item("focus_frost"))&&recipe.componentStacks().get(4).is(net.minecraft.world.item.Items.CACTUS)&&recipe.aspects().getAmount(thaumcraft.api.aspects.Aspect.HUNGER)==64&&recipe.aspects().getAmount(thaumcraft.api.aspects.Aspect.AIR)==50,"original infusion components/aspects");check(dev.eugheist.tc4modern.InfusionItemRecipes.match(recipe.componentStacks(),new net.minecraft.world.item.ItemStack(KamiTools.SWORD.get()),java.util.Set.of("ICHOR_SWORD_GEM"))==recipe,"native infusion matcher");
  System.out.println("TT AWAKENED SWORD AUDIT: ALL PASS (real attacks/same class/range/recursion/soul reserve/cap/hurtTime/resistance/damage/overflow/persistence/infusion)");
 }finally{entities.forEach(net.minecraft.world.entity.Entity::discard);SoulHearts.set(player,0);}
 }
}
